import { defer } from './defer.js';
import { DisposeInterruption } from './interruptions.js';
/**
 * Disposer class, providing a dispose function and a disposed Promise.
 */ export class Disposer extends AbortController {
    #deferred = defer();
    constructor(params = {}){
        super();
        let disposing = false;
        this.signal.addEventListener('abort', ()=>{
            if (!disposing) {
                disposing = true;
                if (params.dispose == null) {
                    this.#deferred.resolve();
                } else {
                    params.dispose(this.signal.reason).then(()=>this.#deferred.resolve());
                }
            }
        }, {
            once: true
        });
        params.signal?.addEventListener('abort', ()=>this.dispose(params.signal?.reason), {
            once: true
        });
    }
    get disposed() {
        return this.#deferred.promise;
    }
    dispose(reason) {
        this.abort(reason ?? new DisposeInterruption());
        return this.#deferred.promise;
    }
    [Symbol.asyncDispose]() {
        return this.dispose();
    }
}
